/* Building Ledger — local-first application. All user text is escaped at rendering boundaries. */
'use strict';
const C=Ledger,KEY='building-ledger-v3',$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let recoveryRaw=null,lastSavedRaw=null;
let state,storageBlocked=false,startupMessage='',view='billing',query='',filter='all',printTarget='all',printOutput='bills',deferredInstall;
try{const raw=localStorage.getItem(KEY);recoveryRaw=raw;lastSavedRaw=raw;if(raw){state=C.validate(JSON.parse(raw));}else{const old=localStorage.getItem('dpdc-bill-app-state-v2');state=old?C.migrate(JSON.parse(old)):C.initial();if(old)startupMessage='Your previous readings were imported. Original saved data has been kept.';}}catch(e){state=C.initial();storageBlocked=true;startupMessage='Saved data could not be read. It has not been overwritten. Export a backup or import a valid backup in Settings.';}
const tr=(en,bn)=>state.lang==='bn'?bn:en;
const num=(v,d=2)=>new Intl.NumberFormat(state.banglaDigits?'bn-BD':'en-BD',{maximumFractionDigits:d}).format(v);
const money=v=>'৳'+new Intl.NumberFormat(state.banglaDigits?'bn-BD':'en-BD',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v);
const monthLabel=k=>new Date(Number(k.slice(0,4)),Number(k.slice(5))-1,1).toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{month:'long',year:'numeric'});
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const m=()=>state.months[state.active];
const flat=id=>m().tenants.find(t=>t.id===id);
const statusLabel=s=>({paid:tr('Paid','পরিশোধিত'),partial:tr('Partly paid','আংশিক পরিশোধিত'),unpaid:tr('Unpaid','অপরিশোধিত')})[s];
const extraLabel=k=>({service:tr('Service charge','সার্ভিস চার্জ'),gas:tr('Gas share','গ্যাস বিল'),water:tr('Water share','পানির বিল'),common:tr('Common electricity','কমন বিদ্যুৎ'),late:tr('Late fee','বিলম্ব ফি')})[k];
const icons={billing:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',main:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',history:'<path d="M3 11a9 9 0 1 1 2.6 7M3 4v7h7M12 7v5l3 2"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',print:'<path d="M7 8V3h10v5M7 17H4V9h16v8h-3M7 14h10v7H7z"/>',pay:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.billing}</svg>`;
function btn(label,action,cls='',id=''){return `<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;}
function field(label,path,value,type='number',extra=''){return `<label>${label}<input type="${type}" data-field="${path}" value="${esc(value)}" ${type==='number'?'min="0" max="1000000000000" step="any" inputmode="decimal"':''} ${extra}></label>`;}
function check(label,path,value){return `<label class="check"><input type="checkbox" data-field="${path}" ${value?'checked':''}>${label}</label>`;}
function select(label,path,value,options){return `<label>${label}<select data-field="${path}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function notice(text,error=false){const n=$('#notice');n.hidden=false;n.className='notice no-print'+(error?' error':'');n.textContent=text;}
function storageConflict(){
  storageBlocked=true;recoveryRaw=null;$('#workspace').inert=true;$('#navigation').inert=true;$('#language').disabled=true;
  $('#saveStatus').dataset.saved='false';$('#saveStatus').textContent=tr('Not saved · reload required','সংরক্ষিত নয় · আবার লোড করুন');
  notice(tr('Records changed in another tab. This tab is paused to protect the newer saved records. Export unsaved work if needed, then reload.','অন্য ট্যাবে হিসাব বদলেছে। নতুন সংরক্ষিত হিসাব রক্ষায় এই ট্যাব বন্ধ রাখা হয়েছে। প্রয়োজনে অসংরক্ষিত কাজ এক্সপোর্ট করে পুনরায় লোড করুন।'),true);
  modal(tr('Newer records found','নতুন হিসাব পাওয়া গেছে'),`<p>${tr('Another tab saved changes. Export this tab’s unsaved copy if needed, then reload the newer records.','অন্য ট্যাবে পরিবর্তন সংরক্ষিত হয়েছে। প্রয়োজনে এই ট্যাবের অসংরক্ষিত কপি নিন, তারপর নতুন হিসাব লোড করুন।')}</p>`,btn(tr('Export unsaved copy','অসংরক্ষিত কপি নিন'),'backup')+btn(tr('Reload saved records','সংরক্ষিত হিসাব লোড করুন'),'reload','primary'));
}
function save(){
  $('#saveStatus').dataset.saved='false';
  if(storageBlocked){$('#saveStatus').textContent=tr('Not saved · restore required','সংরক্ষিত নয় · পুনরুদ্ধার করুন');return;}
  try{if(localStorage.getItem(KEY)!==lastSavedRaw){storageConflict();return;}const raw=JSON.stringify(state);localStorage.setItem(KEY,raw);lastSavedRaw=raw;$('#saveStatus').dataset.saved='true';$('#saveStatus').textContent=DriveBackup.saveLabel();Features.onSaved();}
  catch(e){$('#saveStatus').textContent=tr('Not saved','সংরক্ষিত হয়নি');notice(tr('Unable to save. Export a JSON backup in Settings before closing.','সংরক্ষণ করা যায়নি। বন্ধ করার আগে সেটিংস থেকে JSON ব্যাকআপ নিন।'),true);}
}
function safeMain(){try{return C.mainBill(m());}catch{return null;}}
function actual(){return m().actual===''?safeMain()?.total??0:C.number(m().actual);}
function kv(label,value,cls=''){return `<div class="kv"><span>${label}</span><strong class="${cls}">${value}</strong></div>`;}
function monthSelect(){return `<label>${tr('Billing month','বিলের মাস')}<select id="monthSelect">${Object.keys(state.months).sort().reverse().map(k=>`<option value="${k}" ${k===state.active?'selected':''}>${monthLabel(k)}</option>`).join('')}</select></label>`;}
function title(heading,description,actions=''){return `<div class="page-title"><div><h1>${heading}</h1><p>${description}</p></div><div class="toolbar">${actions}</div></div>`;}
function render(){
  PrintDesign.configure();BillMessaging.configure();
  document.documentElement.lang=state.lang;document.title=`${tr('Building Ledger','বিল্ডিং লেজার')} · ${monthLabel(state.active)}`;
  $('#workspaceName').textContent=state.building||tr('Electricity & collections','বিদ্যুৎ বিল ও আদায়');
  $('#language').textContent=state.lang==='en'?'বাংলা':'English';$('#language').lang=state.lang==='en'?'bn':'en';
  $('#navigation').innerHTML=[['billing',tr('Tenant bills','ভাড়াটিয়ার বিল')],['main',tr('Main meter','প্রধান মিটার')]].map(([k,l])=>`<a href="#${k}" ${view===k?'aria-current="page"':''}>${icon(k)}${l}</a>`).join('')+`<div class="secondary-nav"><a href="#history" ${view==='history'?'aria-current="page"':''}>${icon('history')}${tr('History','ইতিহাস')}</a><a href="#settings" ${view==='settings'?'aria-current="page"':''}>${icon('settings')}${tr('Settings','সেটিংস')}</a></div>`;
  $('#workspace').innerHTML=({billing:billingView,main:mainView,history:historyView,settings:settingsView})[view]();
  if(m().finalizedAt&&['billing','main'].includes(view))$('#workspace').insertAdjacentHTML('afterbegin',`<div class="locked-banner">${tr('This month is finalized. Readings and charges are locked; payments can still be recorded.','এই মাস চূড়ান্ত করা হয়েছে। রিডিং ও চার্জ লক করা; পেমেন্ট নেওয়া যাবে।')} ${btn(tr('Reopen month','মাস পুনরায় খুলুন'),'reopen','small')}</div>`);
  if(view==='billing'){updateTotals();applyFilter();}if(view==='main')updateMain();
  Features.mount();DriveBackup.mount();save();
}
function billingView(){const a=m();return title(tr('Monthly tenant bills','মাসিক ভাড়াটিয়ার বিল'),tr('Read meters, review charges, and keep collections in one place.','রিডিং, বিল এবং আদায়ের হিসাব এক জায়গায় রাখুন।'),monthSelect()+btn(icon('arrow')+tr('Start next month','পরের মাস শুরু করুন'),'next','primary'))+`<section class="stats" id="stats" aria-label="${tr('Monthly totals','মাসিক হিসাব')}"></section><div class="billing-grid"><section class="sheet"><div class="sheet-head"><div><h2>${tr('Readings & balances','রিডিং ও বকেয়া')}</h2><p>${tr('Select a flat name to edit its rate, phone or extra charges.','দর, ফোন বা অতিরিক্ত চার্জ পরিবর্তনে ফ্ল্যাটের নাম বাছুন।')}</p></div>${btn(icon('print')+tr('Print / share bills','বিল প্রিন্ট / শেয়ার'),'print-all')}</div><div class="list-tools"><input id="search" type="search" value="${esc(query)}" placeholder="${tr('Find a flat or phone','ফ্ল্যাট বা ফোন খুঁজুন')}" aria-label="${tr('Find a flat or phone','ফ্ল্যাট বা ফোন খুঁজুন')}"><select id="filter" aria-label="${tr('Filter payment status','পেমেন্ট অবস্থা বাছুন')}">${[['all',tr('All flats','সব ফ্ল্যাট')],['unpaid',statusLabel('unpaid')],['partial',statusLabel('partial')],['paid',statusLabel('paid')]].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select></div><div class="message-tools"><p class="messaging-hint">${tr('SMS uses a short bill summary. WhatsApp uses selected bill details. Review the message and tap Send in your messaging app.','SMS-এ সংক্ষিপ্ত বিল যাবে। WhatsApp-এ বাছাই করা বিবরণ থাকবে। মেসেজ দেখে মেসেজ অ্যাপে Send চাপুন।')}</p>${BillMessaging.languageControl('messageLanguage')}</div><div class="ledger-head" aria-hidden="true"><span>${tr('Flat / unit rate','ফ্ল্যাট / ইউনিট দর')}</span><span>${tr('Previous','পূর্ববর্তী')}</span><span>${tr('Current','বর্তমান')}</span><span class="text-right">${tr('Units','ইউনিট')}</span><span class="text-right">${tr('Balance','বকেয়া')}</span><span class="text-right">${tr('Actions','কাজ')}</span></div><div id="tenantRows">${a.tenants.map(row).join('')}</div><p class="empty" id="noMatches" hidden>${tr('No flats match. Clear the search or choose All flats.','কোনো ফ্ল্যাট মেলেনি। খোঁজ মুছুন অথবা সব ফ্ল্যাট বাছুন।')}</p><div class="sheet-foot"><span class="small-text muted" id="flatCount"></span><div class="toolbar">${btn(icon('plus')+tr('Add flat','ফ্ল্যাট যোগ করুন'),'add','small')}${btn(tr('Reading sheet','রিডিং তালিকা'),'reading-sheet','small')}${btn(icon('billing')+tr('Tenant slips','ভাড়াটিয়ার স্লিপ'),'tenant-slips','small')}</div></div></section><aside class="sheet settlement"><div class="side-section"><h2>${tr('This month’s setup','এই মাসের সেটিংস')}</h2><div class="stack">${field(tr('Shared rate (৳ / unit)','সাধারণ দর (৳ / ইউনিট)'),'month.rate',a.rate,'number',a.finalizedAt?'disabled':'')}${field(tr('Collection due date','বিল পরিশোধের শেষ তারিখ'),'month.due',a.due,'date',a.finalizedAt?'disabled':'')}</div><p>${tr('A flat-specific rate overrides the shared rate.','ফ্ল্যাটের নিজস্ব দর সাধারণ দরের পরিবর্তে প্রযোজ্য হবে।')}</p>${btn(tr('Review & finalize month','পর্যালোচনা ও চূড়ান্ত করুন'),'finalize','',a.key)}</div><div class="side-section"><h2>${tr('Main meter reconciliation','প্রধান মিটারের সাথে মিল')}</h2><div id="reconciliation"></div><a href="#main">${tr('Review main meter','প্রধান মিটার পর্যালোচনা')}</a><p>${tr('The unit gap includes unmetered usage and reading differences; it is not proof of line loss.','ইউনিটের ব্যবধানে কমন ব্যবহার ও রিডিংয়ের পার্থক্য থাকতে পারে; এটি লাইন লসের প্রমাণ নয়।')}</p></div></aside></div>`;}
function row(t){const b=C.bill(t,m()),locked=m().finalizedAt?'disabled':'';return `<article class="tenant-row" data-tenant="${esc(t.id)}"><div class="tenant-identity">${btn(esc(t.name),'edit','flat-button',t.id)}<span class="tenant-id">${money(b.rate)} / ${tr('unit','ইউনিট')}${t.rate!==''?' · '+tr('custom','নিজস্ব'):''}</span></div><label><span class="mobile-label">${tr('Previous reading','পূর্ববর্তী রিডিং')}</span><input type="number" inputmode="decimal" min="0" max="1000000000000" step="any" data-reading="prev" data-id="${esc(t.id)}" aria-label="${esc(t.name)} · ${tr('Previous reading','পূর্ববর্তী রিডিং')}" value="${esc(t.prev)}" ${locked}></label><label><span class="mobile-label">${tr('Current reading','বর্তমান রিডিং')}</span><input type="number" inputmode="decimal" min="0" max="1000000000000" step="any" data-reading="curr" data-id="${esc(t.id)}" aria-label="${esc(t.name)} · ${tr('Current reading','বর্তমান রিডিং')}" aria-describedby="err-${esc(t.id)}" value="${esc(t.curr)}" ${b.invalid?'aria-invalid="true"':''} ${locked}></label><div class="row-number"><span class="mobile-label">${tr('Units','ইউনিট')}</span><span data-units>${b.invalid?'—':num(b.units)}</span></div><div class="row-balance"><span data-balance>${b.invalid?'—':money(Math.abs(b.balance))}</span><span data-status class="badge ${b.status}">${b.invalid?tr('Check reading','রিডিং যাচাই করুন'):b.balance<0?tr('Credit available','অগ্রিম জমা'):b.total===0?tr('No charges','কোনো চার্জ নেই'):statusLabel(b.status)}</span></div><div class="row-actions"><button class="icon-button" data-action="payment" data-id="${esc(t.id)}" title="${tr('Record payment','পেমেন্ট নিন')}" aria-label="${tr('Record payment','পেমেন্ট নিন')} · ${esc(t.name)}">${icon('pay')}</button><button class="icon-button" data-action="print" data-id="${esc(t.id)}" title="${tr('Preview bill','বিল দেখুন')}" aria-label="${tr('Preview bill','বিল দেখুন')} · ${esc(t.name)}">${icon('print')}</button></div><p class="row-error" id="err-${esc(t.id)}" ${b.invalid?'':'hidden'}>${tr('Current reading is lower than previous. Correct it before billing.','বর্তমান রিডিং পূর্ববর্তীর চেয়ে কম। বিল করার আগে সংশোধন করুন।')}</p>${BillMessaging.controls(t)}</article>`;}
function updateRow(id){const t=flat(id),b=C.bill(t,m()),r=document.querySelector(`[data-tenant="${CSS.escape(id)}"]`);if(!r)return;r.querySelector('[data-units]').textContent=b.invalid?'—':num(b.units);r.querySelector('[data-balance]').textContent=b.invalid?'—':money(Math.abs(b.balance));const s=r.querySelector('[data-status]');s.textContent=b.invalid?tr('Check reading','রিডিং যাচাই করুন'):b.balance<0?tr('Credit available','অগ্রিম জমা'):b.total===0?tr('No charges','কোনো চার্জ নেই'):statusLabel(b.status);s.className='badge '+b.status;r.querySelector('.row-error').hidden=!b.invalid;r.querySelector('[data-reading=curr]').setAttribute('aria-invalid',String(b.invalid));Features.updateUsage(id);}
function updateTotals(){const s=C.totals(m());$('#stats').innerHTML=[[tr('Tenant charges','ভাড়াটিয়ার মোট বিল'),money(s.billed),tr('Includes arrears & extra charges','বকেয়া ও অতিরিক্ত চার্জসহ')],[tr('Collected','আদায় হয়েছে'),money(s.paid),tr('Payments recorded this month','এই মাসের নথিভুক্ত পেমেন্ট')],[tr('Outstanding','বাকি আছে'),money(s.outstanding),tr('Across all flats','সব ফ্ল্যাট মিলিয়ে')],[tr('Metered consumption','মোট মিটার ব্যবহার'),num(s.units)+' '+tr('units','ইউনিট'),s.invalid?tr(`${s.invalid} reading(s) need correction`,`${num(s.invalid)}টি রিডিং সংশোধন করুন`):tr(`${m().tenants.length} flats this month`,`${num(m().tenants.length)}টি ফ্ল্যাট এই মাসে`)]].map(([l,v,n])=>`<div><div class="stat-label">${l}</div><div class="stat-value">${v}</div><div class="stat-note">${n}</div></div>`).join('');const b=safeMain(),cost=actual(),gap=b?C.round(b.units-s.units):null,suggest=s.units&&!s.invalid?C.round(cost/s.units):null;$('#reconciliation').innerHTML=kv(tr('Main consumption','প্রধান মিটার ব্যবহার'),b?num(b.units)+' '+tr('units','ইউনিট'):'—')+kv(tr('Tenant consumption','ভাড়াটিয়ার ব্যবহার'),num(s.units)+' '+tr('units','ইউনিট'))+kv(tr('Unallocated units','অনির্ধারিত ইউনিট'),gap===null?'—':num(gap))+kv(tr('Main bill','প্রধান বিল'),money(cost))+kv(tr('Tenant energy charges','ভাড়াটিয়ার বিদ্যুৎ চার্জ'),money(s.energy))+kv(tr('Energy shortfall / surplus¹','বিদ্যুৎ ঘাটতি / উদ্বৃত্ত¹'),money(C.round(cost-s.energy)))+`<p>¹ ${tr('Positive = shortfall; negative = surplus. Arrears and other charges excluded.','ধনাত্মক = ঘাটতি; ঋণাত্মক = উদ্বৃত্ত। বকেয়া ও অন্য চার্জ বাদ।')}</p>`+kv(tr('Break-even unit rate','সমান খরচের ইউনিট দর'),suggest===null?'—':money(suggest))+btn(tr('Use suggested rate','প্রস্তাবিত দর ব্যবহার'),'suggest-rate','small');$('#flatCount').textContent=tr(`${m().tenants.length} flats · changes save automatically`,`${num(m().tenants.length)}টি ফ্ল্যাট · পরিবর্তন স্বয়ংক্রিয়ভাবে সংরক্ষিত হয়`);}
function applyFilter(){let count=0;for(const t of m().tenants){const visible=(!query||(t.name+' '+t.phone).toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||C.bill(t,m()).status===filter);const el=document.querySelector(`[data-tenant="${CSS.escape(t.id)}"]`);if(el)el.hidden=!visible;if(visible)count++;}if($('#noMatches'))$('#noMatches').hidden=!!count;}
function mainView(){const a=m().main,lock=m().finalizedAt?'disabled':'';return title(tr('Main meter','প্রধান মিটার'),tr('Calculate the residential bill and compare it with your official bill.','আবাসিক বিল হিসাব করুন ও অফিসিয়াল বিলের সাথে মিলিয়ে নিন।'),monthSelect()+select(tr('PDF language','PDF-এর ভাষা'),'print.language',state.print.language,[['en','English'],['bn','বাংলা']])+btn(icon('print')+tr('Print summary','সারাংশ প্রিন্ট'),'main-print'))+`<div class="main-grid"><section class="sheet"><div class="sheet-head"><h2>${tr('Readings & connection','রিডিং ও সংযোগ')}</h2></div><fieldset class="sheet-body" ${lock}><div class="form-grid">${field(tr('Previous reading','পূর্ববর্তী রিডিং'),'main.prev',a.prev)}${field(tr('Current reading','বর্তমান রিডিং'),'main.curr',a.curr)}<div class="full">${check(tr('Enter consumption directly','সরাসরি ব্যবহার লিখুন'),'main.direct',a.direct)}</div><div class="full" id="directUnits" ${a.direct?'':'hidden'}>${field(tr('Units consumed','ব্যবহৃত ইউনিট'),'main.units',a.units)}</div>${select(tr('Meter type','মিটারের ধরন'),'main.type',a.type,[['postpaid',tr('Postpaid','পোস্টপেইড')],['prepaid',tr('Prepaid','প্রিপেইড')]])}${select(tr('Connection phase','সংযোগের ফেজ'),'main.phase',a.phase,[['single',tr('Single phase','সিঙ্গেল ফেজ')],['three',tr('Three phase','থ্রি ফেজ')]])}${field(tr('Meter rent (৳)','মিটার ভাড়া (৳)'),'main.rent',a.rent)}${field(tr('Prepaid rebate (%)','প্রিপেইড রেয়াত (%)'),'main.rebate',a.rebate,'number','max="100"')}<div class="full">${check(tr('Include demand charge','ডিমান্ড চার্জ যোগ করুন'),'main.demand',a.demand)}</div><div class="full form-grid" id="demandFields" ${a.demand?'':'hidden'}>${field(tr('Sanctioned load (kW)','অনুমোদিত লোড (কিলোওয়াট)'),'main.load',a.load)}${field(tr('Rate (৳ / kW)','দর (৳ / কিলোওয়াট)'),'main.demandRate',a.demandRate)}</div><div class="full">${check(tr('Include 5% VAT','৫% ভ্যাট যোগ করুন'),'main.vat',a.vat)}${check(tr('Apply lifeline rate at 50 units or below','৫০ ইউনিট বা কমে লাইফলাইন দর প্রয়োগ করুন'),'main.lifeline',a.lifeline)}</div></div><details class="section-gap"><summary>${tr('Tariff presets & custom rates','ট্যারিফ প্রিসেট ও নিজস্ব দর')}</summary><p class="hint">${tr('DPDC residential table, June 2026. Rates are not updated automatically. Check demand, rent, VAT and rebate against your bill.','ডিপিডিসি আবাসিক তালিকা, জুন ২০২৬। দর স্বয়ংক্রিয়ভাবে হালনাগাদ হয় না। ডিমান্ড, ভাড়া, ভ্যাট ও রেয়াত বিলের সাথে যাচাই করুন।')}</p><a class="small-text" href="https://dpdc.gov.bd/pages/static-pages/6922de6f933eb65569e1a9c4" target="_blank" rel="noopener">${tr('Official DPDC tariff source','ডিপিডিসির অফিসিয়াল ট্যারিফ')}</a><div class="toolbar section-gap">${select(tr('Preset','প্রিসেট'),'main.preset',a.preset,[['2026-06',tr('June 2026 residential','জুন ২০২৬ আবাসিক')],['2024-02',tr('February 2024 residential','ফেব্রুয়ারি ২০২৪ আবাসিক')],['custom',tr('Custom / imported','নিজস্ব / আমদানিকৃত')]])}${btn(tr('Apply preset','প্রিসেট প্রয়োগ'),'preset')}</div><div class="tariff-rows section-gap">${a.rates.map((r,i)=>`<div class="tariff-row"><span>${i===0?tr('Lifeline','লাইফলাইন'):tr('Band','ধাপ')+' '+num(i)}</span>${field(tr('Up to units','সর্বোচ্চ ইউনিট'),'limit.'+i,a.limits[i]??'','number',i===6?'disabled placeholder="∞"':'')}${field(tr('৳ / unit','৳ / ইউনিট'),'rate.'+i,r)}</div>`).join('')}</div></details></fieldset></section><aside class="stack"><section class="sheet"><div class="sheet-head"><h2>${tr('Bill breakdown','বিলের বিবরণ')}</h2></div><div class="sheet-body" id="mainResult" aria-live="polite"></div></section><section class="sheet"><div class="sheet-body"><h2>${tr('Official bill override','অফিসিয়াল বিল')}</h2><p class="hint">${tr('Optional: use the actual bill amount for reconciliation. Leave blank to use the calculator.','মিলানোর জন্য প্রকৃত বিলের পরিমাণ লিখতে পারেন। ক্যালকুলেটরের হিসাব ব্যবহার করতে খালি রাখুন।')}</p><div class="section-gap">${field(tr('Actual total bill (৳)','প্রকৃত মোট বিল (৳)'),'month.actual',m().actual,'number',lock)}</div><p class="hint">${tr('Arrears and surcharges on the DPDC bill are not modeled by the calculator.','ডিপিডিসি বিলের বকেয়া ও সারচার্জ ক্যালকুলেটরে ধরা হয় না।')}</p></div></section></aside></div>`;}
function breakdown(b){return `<table class="breakdown"><thead><tr><th>${tr('Charge','চার্জ')}</th><th>${tr('Amount','পরিমাণ')}</th></tr></thead><tbody>${b.lines.map(l=>`<tr><td>${num(l.units)} × ${money(l.rate)}</td><td>${money(l.amount)}</td></tr>`).join('')}<tr><td>${tr('Energy charge','বিদ্যুৎ চার্জ')}</td><td>${money(b.energy)}</td></tr><tr><td>${tr('Demand charge','ডিমান্ড চার্জ')}</td><td>${money(b.demand)}</td></tr><tr><td>${tr('VAT (5%)','ভ্যাট (৫%)')}</td><td>${money(b.vat)}</td></tr><tr><td>${tr('Meter rent','মিটার ভাড়া')}</td><td>${money(b.rent)}</td></tr><tr><td>${tr('Prepaid rebate','প্রিপেইড রেয়াত')}</td><td>−${money(b.rebate)}</td></tr><tr class="grand"><td>${tr('Total payable','মোট প্রদেয়')}</td><td>${money(b.total)}</td></tr></tbody></table>`;}
function updateMain(){try{const b=C.mainBill(m());$('#mainResult').innerHTML=`${kv(tr('Consumption','ব্যবহার'),num(b.units)+' '+tr('units','ইউনিট'))}${breakdown(b)}<p class="hint">${tr('Average cost per unit','ইউনিটপ্রতি গড় খরচ')}: ${money(b.average)}</p>`;}catch(e){$('#mainResult').innerHTML=`<p class="field-error" role="alert">${e.message==='reading'?tr('Current reading must be at least the previous reading. Correct the reading to calculate.','হিসাব করতে বর্তমান রিডিং পূর্ববর্তীর সমান বা বেশি লিখুন।'):tr('Slab limits must increase, rates must be nonnegative, and the last slab must be unlimited. Correct the tariff table.','ধাপের সীমা ক্রমান্বয়ে বাড়তে হবে, দর ঋণাত্মক হবে না এবং শেষ ধাপ অসীম রাখুন।')}</p>`;}}
function historyView(){return title(tr('Monthly history','মাসিক ইতিহাস'),tr('Every month is saved separately. Opening a month does not change its bills.','প্রতিটি মাস আলাদাভাবে সংরক্ষিত। মাস খুললে বিল পরিবর্তিত হয় না।'),btn(tr('Export backup','ব্যাকআপ নিন'),'backup'))+`<section class="sheet"><div class="sheet-head"><h2>${tr('Saved months','সংরক্ষিত মাস')}</h2><span class="muted small-text">${tr('On this device','এই ডিভাইসে')}</span></div>${Object.keys(state.months).sort().reverse().map(k=>{const a=state.months[k],s=C.totals(a);return `<div class="history-row"><div><h3>${monthLabel(k)}</h3><small>${num(a.tenants.length)} ${tr('flats','ফ্ল্যাট')} · ${a.finalizedAt?tr('Finalized','চূড়ান্ত'):tr('Open','খোলা')}</small></div><div><small>${tr('Billed','মোট বিল')}</small><div class="stat-value">${money(s.billed)}</div></div><div><small>${tr('Collected','আদায়')}</small><div class="stat-value">${money(s.paid)}</div></div><div><small>${tr('Outstanding','বাকি')}</small><div class="stat-value">${money(s.outstanding)}</div></div>${btn(tr('Open month','মাস খুলুন'),'open-month','',k)}</div>`;}).join('')}</section><p class="hint section-gap">${tr('Carry-over copies unpaid balances once. If you reopen an earlier month and change payments or charges, review arrears in later months manually.','বকেয়া একবার পরের মাসে নেওয়া হয়। আগের মাসের পেমেন্ট বা চার্জ পরিবর্তন করলে পরের মাসগুলোর বকেয়া নিজে যাচাই করুন।')}</p>`;}
function settingsView(){return title(tr('Settings & backup','সেটিংস ও ব্যাকআপ'),tr('Building identity, billing preferences and a copy of your records.','ভবনের পরিচয়, বিলের পছন্দ ও হিসাবের ব্যাকআপ।'))+`<section class="settings-row"><div><h2>${tr('Building identity','ভবনের পরিচয়')}</h2><p>${tr('Shown on bills, receipts and reading sheets.','বিল, রসিদ ও রিডিং তালিকায় দেখাবে।')}</p></div><div class="sheet sheet-body form-grid">${field(tr('Building / house name','ভবন / বাড়ির নাম'),'state.building',state.building,'text','maxlength="100"')}${field(tr('Address','ঠিকানা'),'state.address',state.address,'text','maxlength="200"')}<label class="full">${tr('Bill footer note','বিলের নিচের নোট')}<textarea rows="3" maxlength="500" data-field="state.note">${esc(state.note)}</textarea></label></div></section><section class="settings-row"><div><h2>${tr('Display & billing','প্রদর্শন ও বিলিং')}</h2><p>${tr('These billing preferences apply to the selected month.','বিলিংয়ের পছন্দ নির্বাচিত মাসের জন্য প্রযোজ্য।')}</p></div><div class="sheet sheet-body">${check(tr('Show Bangla numerals','বাংলা সংখ্যা দেখান'),'state.banglaDigits',state.banglaDigits)}<fieldset ${m().finalizedAt?'disabled':''}>${check(tr('Round tenant totals to the nearest taka','ভাড়াটিয়ার মোট বিল নিকটতম টাকায় করুন'),'month.roundTaka',m().roundTaka)}</fieldset><p class="hint">${tr('Rounding applies to the total and is hidden on tenant slips. Reopen a finalized month to change billing.','রাউন্ডিং মোট বিলে প্রযোজ্য হবে; ভাড়াটিয়ার স্লিপে আলাদা লাইন দেখাবে না। বিলিং পরিবর্তনে চূড়ান্ত মাস পুনরায় খুলুন।')}</p></div></section><section class="settings-row"><div><h2>${tr('Bill messages','বিলের মেসেজ')}</h2><p>${tr('Choose a language for SMS, WhatsApp and copied bill text.','SMS, WhatsApp ও কপি করা বিলের ভাষা বাছুন।')}</p></div><div class="sheet sheet-body">${BillMessaging.languageControl('settingsMessageLanguage')}<p class="hint">${tr('English messages use English numerals; Bangla messages use Bangla numerals. SMS includes a short summary with units, total, paid, balance and due date. WhatsApp and copied text keep the selected document details.','ইংরেজি মেসেজে ইংরেজি সংখ্যা ও বাংলা মেসেজে বাংলা সংখ্যা থাকবে। SMS-এ ইউনিট, মোট বিল, জমা, বকেয়া ও শেষ তারিখের সংক্ষিপ্ত হিসাব যাবে। WhatsApp ও কপি করা লেখায় নথির বাছাই করা বিবরণ থাকবে।')}</p></div></section><section class="settings-row"><div><h2>${tr('Backups & exports','ব্যাকআপ ও এক্সপোর্ট')}</h2><p>${tr('Browser storage stays on this device. Keep a backup before clearing browser data or changing phones.','ব্রাউজারের তথ্য এই ডিভাইসেই থাকে। ব্রাউজারের তথ্য মোছা বা ফোন পরিবর্তনের আগে ব্যাকআপ নিন।')}</p></div><div class="sheet sheet-body"><div class="export-actions">${btn(tr('Export JSON backup','JSON ব্যাকআপ নিন'),'backup')}${btn(tr('Import JSON backup','JSON ব্যাকআপ আনুন'),'import')}${btn(tr('Export month CSV','মাসের CSV নিন'),'csv')}</div><p class="hint">${tr('JSON includes all months, names and phone numbers. CSV contains the selected month for Excel. Import validates the file before asking to replace data.','JSON-এ সব মাস, নাম ও ফোন থাকে। Excel-এর CSV-তে নির্বাচিত মাস থাকে। তথ্য প্রতিস্থাপনের আগে ফাইল যাচাই করা হয়।')}</p></div></section><section class="settings-row"><div><h2>${tr('Install & work offline','ইনস্টল ও অফলাইনে ব্যবহার')}</h2><p>${tr('Billing works offline. Google Drive backup is optional and requires an internet connection.','বিলিং অফলাইনে চলে। Google Drive ব্যাকআপ ঐচ্ছিক; ইন্টারনেট লাগবে।')}</p></div><div class="sheet sheet-body"><p>${tr('On localhost or HTTPS, open the app once online, then use your browser’s Install app / Add to Home Screen menu. Print → Save as PDF creates a PDF using your browser.','লোকালহোস্ট বা HTTPS-এ একবার অনলাইনে খুলুন, তারপর ব্রাউজারের Install app / Add to Home Screen ব্যবহার করুন। Print → Save as PDF দিয়ে PDF তৈরি করুন।')}</p><p class="hint">${tr('A downloaded HTML file can calculate locally; installation and reliable offline reopening require the local server or HTTPS.','ডাউনলোড করা HTML-এ হিসাব করা যায়; ইনস্টল ও নির্ভরযোগ্য অফলাইন ব্যবহারে লোকাল সার্ভার বা HTTPS লাগে।')}</p></div></section>`;}
function modal(title,body,actions){const d=$('#editor');d.innerHTML=`<div class="dialog-head"><h2 id="dialogTitle">${title}</h2><button class="icon-button" data-action="close" aria-label="${tr('Close','বন্ধ করুন')}">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${actions}</div>`;if(!d.open)d.showModal();}
function confirmAction(title,body,action,label){modal(title,`<p>${body}</p>`,btn(tr('Cancel','বাতিল'),'close')+btn(label,action,'primary'));}
function editTenant(id){const t=flat(id),lock=m().finalizedAt?'disabled':'';modal(esc(t.name),`<form id="tenantForm" data-id="${esc(id)}"><fieldset class="stack" ${lock}><div class="form-grid"><label>${tr('Flat / tenant name','ফ্ল্যাট / ভাড়াটিয়ার নাম')}<input name="name" required maxlength="100" value="${esc(t.name)}"></label><label>${tr('WhatsApp phone','হোয়াটসঅ্যাপ ফোন')}<input name="phone" type="tel" autocomplete="tel" maxlength="25" placeholder="01XXXXXXXXX" value="${esc(t.phone)}"></label><label>${tr('Custom rate (৳ / unit)','নিজস্ব দর (৳ / ইউনিট)')}<input name="rate" type="number" min="0" max="1000000000000" step="any" value="${esc(t.rate)}" placeholder="${esc(m().rate)}"></label><label>${tr('Opening arrears (৳)','আগের বকেয়া (৳)')}<input name="arrears" type="number" min="0" max="1000000000000" step="any" required value="${esc(t.arrears)}"></label></div><p class="hint">${tr('Leave custom rate blank to follow the shared rate. Enter 0 for free units.','সাধারণ দর রাখতে নিজস্ব দর খালি রাখুন। বিনামূল্যে ইউনিটের জন্য ০ লিখুন।')}</p><details><summary>${tr('Optional extra charges','ঐচ্ছিক অতিরিক্ত চার্জ')}</summary><div class="form-grid">${Object.entries(t.extras).map(([k,v])=>`<label>${extraLabel(k)} (৳)<input name="extra-${k}" type="number" min="0" max="1000000000000" step="any" value="${v}"></label>`).join('')}</div><p class="hint">${tr('Late fee applies only after the due date. Finalizing freezes whether it applies. These are this flat’s amounts; common charges are not split automatically.','শেষ তারিখ পার হলে বিলম্ব ফি প্রযোজ্য। চূড়ান্ত করলে তা স্থির হয়। কমন চার্জ স্বয়ংক্রিয়ভাবে ভাগ হয় না; এই ফ্ল্যাটের অংশ লিখুন।')}</p></details></fieldset><p id="tenantError" class="field-error" role="alert"></p></form>`,(!m().finalizedAt?btn(tr('Remove flat','ফ্ল্যাট সরান'),'remove-ask','danger',id):'')+btn(tr('Close','বন্ধ করুন'),'close')+(!m().finalizedAt?`<button class="primary" type="submit" form="tenantForm">${tr('Save flat','ফ্ল্যাট সংরক্ষণ')}</button>`:''));}
function paymentDialog(id){const t=flat(id),b=C.bill(t,m());if(b.invalid)return notice(tr('Correct the flat’s current reading before recording payment.','পেমেন্ট নেওয়ার আগে ফ্ল্যাটের বর্তমান রিডিং সংশোধন করুন।'),true);modal(tr('Payment · ','পেমেন্ট · ')+esc(t.name),`${kv(tr('Bill total','মোট বিল'),money(b.total))}${kv(tr('Already paid','পরিশোধিত'),money(b.paid))}${kv(b.balance<0?tr('Credit available','অগ্রিম জমা'):tr('Balance due','প্রদেয় বকেয়া'),money(Math.abs(b.balance)))}<form id="paymentForm" data-id="${esc(id)}" class="form-grid section-gap"><label>${tr('Amount received (৳)','প্রাপ্ত টাকা (৳)')}<input name="amount" type="number" min="0.01" max="${Math.max(0,b.balance)}" step="0.01" required value="${Math.max(0,b.balance)}"></label><label>${tr('Payment date','পেমেন্টের তারিখ')}<input name="date" type="date" max="${C.today()}" required value="${C.today()}"></label><label class="full">${tr('Payment note (optional)','পেমেন্ট নোট (ঐচ্ছিক)')}<input name="note" maxlength="100" placeholder="${tr('Cash, bKash reference…','নগদ, বিকাশ রেফারেন্স…')}"></label><p id="paymentError" class="field-error full" role="alert"></p></form><h3 class="section-gap">${tr('Payment records','পেমেন্টের তালিকা')}</h3>${t.payments.length?t.payments.map(p=>`<div class="payment-entry"><span>${dateLabel(p.date)} · ${money(p.amount)}<br><span class="muted">${esc(p.note||'')}</span></span><div>${btn(tr('Receipt','রসিদ'),'receipt','small',id+'|'+p.id)}${btn(tr('Remove','সরান'),'delete-payment-ask','small danger',id+'|'+p.id)}</div></div>`).join(''):`<p class="hint">${tr('No payments recorded yet.','এখনও পেমেন্ট নেওয়া হয়নি।')}</p>`}`,btn(tr('Close','বন্ধ করুন'),'close')+`<button class="primary" type="submit" form="paymentForm" ${b.balance<=0?'disabled':''}>${tr('Record payment','পেমেন্ট সংরক্ষণ')}</button>`);}
function invoiceHeader(type,reference){return PrintDesign.header(type,reference);}
function invoice(t){return PrintDesign.slip(t);}
function printStudio(id='all',output='bills'){
  if(id!=='all'&&m().tenants.some(t=>t.id===id&&C.bill(t,m()).invalid))return notice(tr('Correct invalid readings before printing or sharing bills.','বিল প্রিন্ট বা শেয়ারের আগে ভুল রিডিং সংশোধন করুন।'),true);
  printTarget=id;printOutput=output;PrintSelection.configure(id);
  const options={readings:tr('Meter readings & units','মিটার রিডিং ও ইউনিট'),rate:tr('Unit rate','ইউনিট দর'),charges:tr('Itemized extra charges','আলাদা অতিরিক্ত চার্জ'),arrears:tr('Previous arrears','আগের বকেয়া'),payments:tr('Payments received','প্রাপ্ত পেমেন্ট'),due:tr('Due date','শেষ তারিখ'),phone:tr('Tenant phone','ভাড়াটিয়ার ফোন'),signature:tr('Signature lines','স্বাক্ষরের স্থান'),note:tr('Footer note','নিচের নোট')};
  if(output==='bills')options.compact=tr('Two-column cut-out slips','দুই কলামে কাটার স্লিপ');
  const outputs=[['vouchers',tr('Individual payment vouchers · up to 15/page','পৃথক পেমেন্ট ভাউচার · পাতায় সর্বোচ্চ ১৫টি')],['bills',tr('Detailed tenant bills','বিস্তারিত ভাড়াটিয়ার বিল')]];
  if(id==='all')outputs.push(['statement',tr('Reading sheet / master statement','রিডিং তালিকা / মূল বিবরণী')]);
  const d=$('#printStudio');d.innerHTML=`<div class="dialog-head"><div><h2 id="printTitle">${tr('Print & PDF center','প্রিন্ট ও PDF সেন্টার')}</h2><p class="hint">${id==='all'?monthLabel(state.active)+' · '+num(m().tenants.length)+' '+tr('flats','ফ্ল্যাট'):esc(flat(id).name)}</p></div><button class="icon-button" data-action="close-print" aria-label="${tr('Close','বন্ধ করুন')}">${icon('close')}</button></div><div class="print-layout"><aside class="print-options"><div class="output-options"><label>${tr('Print layout','প্রিন্টের ধরন')}<select id="printOutput">${outputs.map(([value,label])=>`<option value="${value}" ${value===output?'selected':''}>${label}</option>`).join('')}</select></label>${select(tr('PDF language','PDF-এর ভাষা'),'print.language',state.print.language,[['en','English'],['bn','বাংলা']])}${id==='all'?'':BillMessaging.languageControl('printMessageLanguage')}${id==='all'&&output==='bills'?check(tr('Include master statement','মূল বিবরণী অন্তর্ভুক্ত করুন'),'print.includeStatement',state.print.includeStatement!==false):''}<p id="printLayoutNote" class="hint">${output==='vouchers'?tr('3 columns × up to 5 rows on A4. Long notes or extra details may use fewer slips per page.','A4 পাতায় ৩ কলাম × সর্বোচ্চ ৫ সারি। বড় নোট বা বেশি বিবরণ থাকলে প্রতি পাতায় কম স্লিপ হবে।'):output==='statement'?tr('A complete building reading sheet with totals and custom rates.','মোট হিসাব ও নিজস্ব দরসহ ভবনের সম্পূর্ণ রিডিং তালিকা।'):tr('Detailed bills with optional shared master statement.','ঐচ্ছিক মূল বিবরণীসহ বিস্তারিত বিল।')}</p></div>${PrintSelection.controls()}<fieldset><legend>${tr('Show on document','নথিতে দেখান')}</legend>${Object.entries(options).filter(([key])=>output!=='statement'||!['charges','arrears','phone'].includes(key)).map(([k,v])=>check(v,'print.'+k,state.print[k])).join('')}</fieldset><p class="section-gap">${tr('Hidden details still count toward the total. Use Print → Save as PDF. Choose A4, 100% scale, and turn off browser headers and footers.','লুকানো বিবরণ মোট বিলে ধরা হয়। Print → Save as PDF ব্যবহার করুন। A4, ১০০% স্কেল বাছুন এবং ব্রাউজারের হেডার ও ফুটার বন্ধ রাখুন।')}</p></aside><div class="preview-surface"><div class="print-preview-toolbar"><strong>${tr('Document preview','নথির প্রিভিউ')}</strong><span id="printPageCount" role="status" aria-live="polite"></span></div><div id="billPreview"></div></div></div><div class="dialog-actions">${id==='all'?'':btn('WhatsApp','whatsapp','',id)+btn('SMS','sms','',id)+btn(tr('Copy bill text','বিলের লেখা কপি করুন'),'copy-bill','',id)+btn(tr('Share bill text','বিলের লেখা শেয়ার'),'share','',id)}${btn(icon('print')+tr('Print / Save PDF','প্রিন্ট / PDF সংরক্ষণ'),'print-now','primary')}</div>`;
  refreshPrintPreview();if(!d.open)d.showModal();
}
function refreshPrintPreview(){
  if(!$('#printStudio')||!$('#billPreview'))return;
  try{
    const list=PrintSelection.list();
    if(!list.length){$('#billPreview').innerHTML=`<div class="print-empty"><h3>${tr('No flats selected','কোনো ফ্ল্যাট বাছা হয়নি')}</h3><p>${tr('Choose at least one flat or change the selection filter to preview and print.','প্রিভিউ ও প্রিন্ট করতে অন্তত একটি ফ্ল্যাট বাছুন অথবা বাছাইয়ের ফিল্টার বদলান।')}</p></div>`;$('#printPageCount').textContent=PrintSelection.countLabel();$('#printStudio [data-action="print-now"]').disabled=true;return;}
    if(list.some(t=>C.bill(t,m()).invalid))throw Error('reading');
    $('#billPreview').innerHTML=PrintDesign.preview(printTarget,printOutput,list);
    const pages=$('#billPreview').querySelectorAll('.voucher-page').length;
    if($('#printPageCount'))$('#printPageCount').textContent=printOutput==='vouchers'?tr(`${list.length} flat(s) · ${pages} A4 page(s) · up to 15 vouchers/page`,`${num(list.length)}টি ফ্ল্যাট · ${num(pages)}টি A4 পাতা · প্রতি পাতায় সর্বোচ্চ ১৫টি ভাউচার`):PrintSelection.countLabel()+' · A4';
    const button=$('#printStudio [data-action="print-now"]');if(button)button.disabled=false;
  }catch(error){
    $('#billPreview').innerHTML=`<p class="field-error" role="alert">${esc(errorText(error))}</p>`;
    const button=$('#printStudio [data-action="print-now"]');if(button)button.disabled=true;
    if($('#printPageCount'))$('#printPageCount').textContent=tr('Review document options','নথির সেটিংস যাচাই করুন');
  }
}
function printHTML(html){$('#printArea').lang=PrintDesign.language();$('#printArea').innerHTML=html;window.print();}
function readingSheet(){if(C.totals(m()).invalid)return notice(tr('Correct invalid readings before printing.','প্রিন্টের আগে ভুল রিডিং সংশোধন করুন।'),true);printHTML(`<div class="ref-document" lang="${PrintDesign.language()}"><section class="ref-paper">${PrintDesign.statement()}</section></div>`);}
function receipt(id,pid){const t=flat(id),p=t.payments.find(x=>x.id===pid);if(p)printHTML(PrintDesign.paymentReceipt(t,p));}
function billText(t){return BillMessaging.text(t);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){
  if(storageBlocked&&recoveryRaw!==null){download('building-ledger-recovery-'+C.today()+'.json',recoveryRaw,'application/json');return;}
  const at=new Date().toISOString(),snapshot={...state,lastBackupAt:at,lastBackupMonth:state.active,lastBackupDestination:'download'};delete snapshot.backupPendingSince;
  download('building-ledger-backup-'+C.today()+'.json',JSON.stringify(snapshot,null,2),'application/json');
  state.lastBackupAt=at;state.lastBackupMonth=state.active;state.lastBackupDestination='download';delete state.backupPendingSince;save();Features.onSaved();
}
function csvExport(){const rows=[['Month','Flat','Phone','Previous','Current','Units','Unit rate','Energy','Service','Gas','Water','Common electricity','Late fee','Arrears','Rounding','Total','Paid','Balance','Status','Due date']];for(const t of m().tenants){const b=C.bill(t,m());rows.push([state.active,t.name,t.phone,t.prev,t.curr,b.invalid?'INVALID':b.units,b.rate,b.energy,...b.extras.map(e=>e.amount),b.arrears,b.adjustment,b.total,b.paid,b.balance,b.status,m().due]);}download('building-ledger-'+state.active+'.csv',C.csv(rows),'text/csv;charset=utf-8');}
function errorText(e){return ({reading:tr('Correct readings that are lower than previous readings, including the main meter.','প্রধান মিটারসহ পূর্ববর্তীর চেয়ে কম রিডিং সংশোধন করুন।'),'voucher-too-long':tr('A voucher is too long for A4. Hide its footer note or choose Detailed tenant bills.','একটি ভাউচার A4 পাতার জন্য বেশি বড়। নিচের নোট বন্ধ করুন অথবা বিস্তারিত বিল বাছুন।'),slabs:tr('Correct the tariff limits and rates in Main meter first.','প্রথমে প্রধান মিটারের ট্যারিফ সীমা ও দর সংশোধন করুন।'),exists:tr('The next month already exists. Open it from History.','পরের মাস রয়েছে। ইতিহাস থেকে খুলুন।'),latest:tr('Open the latest saved month before starting the next one.','পরের মাস শুরুর আগে সর্বশেষ সংরক্ষিত মাস খুলুন।'),credit:tr('A flat has an overpayment. Resolve the credit before carrying balances forward.','কোনো ফ্ল্যাটে অতিরিক্ত পেমেন্ট আছে। বকেয়া নেওয়ার আগে তা সমাধান করুন।')})[e.message]||tr('Unable to complete this action. Review the entries and try again.','কাজটি করা যায়নি। তথ্য যাচাই করে আবার চেষ্টা করুন।');}
let pendingImport=null;
document.addEventListener('input',e=>{
  const el=e.target;if(el.id==='search'){query=el.value;applyFilter();return;}
  if(el.dataset.reading){if(m().finalizedAt)return;const t=flat(el.dataset.id);t[el.dataset.reading]=el.value===''?'':Number(el.value);updateRow(t.id);updateTotals();save();return;}
  if(el.dataset.field&&el.type!=='checkbox'&&el.tagName!=='SELECT')changeField(el);
});
document.addEventListener('change',e=>{const el=e.target;if(PrintSelection.change(el))return;if(el.id==='monthSelect'){state.active=el.value;render();return;}if(el.id==='printOutput'){printStudio(printTarget,el.value);$('#printOutput').focus();return;}if(el.id==='filter'){filter=el.value;applyFilter();return;}if(el.dataset.field&&(el.type==='checkbox'||el.tagName==='SELECT'))changeField(el);});
function changeField(el){const [group,key]=el.dataset.field.split('.');const v=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''&&key==='actual'?'':C.number(el.value)):el.value;
  if(['main','month','limit','rate'].includes(group)&&m().finalizedAt)return;
  if(group==='state')state[key]=v;
  if(group==='month')m()[key]=v;
  if(group==='main'){m().main[key]=v;if(key==='phase'){m().main.rent=v==='three'?40:10;const rent=$('[data-field="main.rent"]');if(rent)rent.value=m().main.rent;}if(key==='rebate'&&v>100){m().main.rebate=100;el.value=100;}if(key==='direct')$('#directUnits').hidden=!v;if(key==='demand')$('#demandFields').hidden=!v;}
  if(group==='rate'){m().main.rates[Number(key)]=v;m().main.preset='custom';}
  if(group==='limit'){m().main.limits[Number(key)]=v;m().main.preset='custom';}
  if(group==='state'&&key==='messageLanguage')BillMessaging.syncControls();
  if(group==='print'){state.print[key]=v;if($('#printStudio').open&&$('#billPreview'))refreshPrintPreview();}
  if(view==='billing'){m().tenants.forEach(t=>updateRow(t.id));updateTotals();}if(view==='main')updateMain();
  if(group==='state'&&key==='banglaDigits'){render();return;}if(group==='state'&&key==='building')$('#workspaceName').textContent=state.building||tr('Electricity & collections','বিদ্যুৎ বিল ও আদায়');save();
}
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.reportValidity())return;const data=new FormData(form),id=form.dataset.id,t=flat(id);
  if(form.id==='tenantForm'){if(m().finalizedAt)return;t.name=String(data.get('name')).trim();if(!t.name){$('#tenantError').textContent=tr('Enter a flat name.','ফ্ল্যাটের নাম লিখুন।');return;}t.phone=String(data.get('phone')).trim();t.rate=data.get('rate')===''?'':C.number(data.get('rate'));t.arrears=C.number(data.get('arrears'));for(const k of Object.keys(t.extras))t.extras[k]=C.number(data.get('extra-'+k));$('#editor').close();render();}
  if(form.id==='paymentForm'){const b=C.bill(t,m()),amount=C.round(C.number(data.get('amount')));if(amount<=0||amount>b.balance||String(data.get('date'))>C.today()){$('#paymentError').textContent=tr('Enter a positive amount no greater than the balance and a date up to today.','বকেয়ার বেশি নয় এমন ধনাত্মক টাকা ও আজ পর্যন্ত একটি তারিখ লিখুন।');return;}t.payments.push({id:C.id(),amount,date:data.get('date'),note:String(data.get('note')).trim()});save();paymentDialog(id);if(view==='billing'){updateRow(id);updateTotals();}notice(tr('Payment recorded. Print a receipt from the payment records.','পেমেন্ট সংরক্ষিত। পেমেন্টের তালিকা থেকে রসিদ প্রিন্ট করুন।'));}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.action;try{
  if(['main-print','next','next-confirm','finalize','finalize-confirm','suggest-rate','payment'].includes(a)){const invalid=[...document.querySelectorAll('#workspace input')].find(el=>!el.disabled&&!el.checkValidity());if(invalid){invalid.reportValidity();return notice(tr('Correct the highlighted value before billing. Use a nonnegative number within the allowed range.','বিল করার আগে চিহ্নিত তথ্য ঠিক করুন। নির্ধারিত সীমার মধ্যে শূন্য বা ধনাত্মক সংখ্যা লিখুন।'),true);}}
  if(a==='reload')location.reload();if(a==='close')$('#editor').close();if(a==='close-print')$('#printStudio').close();
  if(a==='edit')editTenant(id);if(a==='payment')paymentDialog(id);if(a==='print')printStudio(id);if(a==='print-all')printStudio();
  if(a==='print-now'){const list=PrintSelection.list();if(!list.length){refreshPrintPreview();return;}if(list.some(t=>C.bill(t,m()).invalid))throw Error('reading');printHTML(printOutput==='vouchers'?PrintDesign.vouchers(list):printOutput==='statement'?PrintDesign.preview('all','statement',list):PrintDesign.packet(list,{includeStatement:printTarget==='all'&&state.print.includeStatement!==false}));}
  if(a==='reading-sheet')printStudio('all','statement');if(a==='tenant-slips')printStudio('all','vouchers');
  if(a==='main-print')printHTML(PrintDesign.mainStatement());
  if(a==='add'){if(m().finalizedAt)return;if(m().tenants.length>=30)return notice(tr('Maximum 30 flats per month.','প্রতি মাসে সর্বোচ্চ ৩০টি ফ্ল্যাট।'),true);const t=C.tenant(m().tenants.length+1);m().tenants.push(t);render();editTenant(t.id);}
  if(a==='remove-ask'){if(m().tenants.length<=1)return notice(tr('Keep at least one flat.','অন্তত একটি ফ্ল্যাট রাখুন।'),true);confirmAction(tr('Remove this flat?','এই ফ্ল্যাট সরাবেন?'),tr('Its readings, charges and payment records will be removed from this month only. Export a backup first if needed.','এই মাস থেকে ফ্ল্যাটের রিডিং, চার্জ ও পেমেন্ট মুছে যাবে। প্রয়োজনে আগে ব্যাকআপ নিন।'),'remove:'+id,tr('Remove flat','ফ্ল্যাট সরান'));}
  if(a.startsWith('remove:')){if(m().finalizedAt)return;m().tenants=m().tenants.filter(t=>t.id!==a.slice(7));$('#editor').close();render();}
  if(a==='delete-payment-ask')confirmAction(tr('Remove this payment?','এই পেমেন্ট সরাবেন?'),tr('The balance will increase by this payment amount. Its receipt will no longer be available.','এই টাকার পরিমাণ বকেয়ায় যোগ হবে। এই পেমেন্টের রসিদ আর থাকবে না।'),'delete-payment:'+id,tr('Remove payment','পেমেন্ট সরান'));
  if(a.startsWith('delete-payment:')){const [tid,pid]=a.slice(15).split('|');flat(tid).payments=flat(tid).payments.filter(p=>p.id!==pid);save();render();paymentDialog(tid);}
  if(a==='receipt'){const [tid,pid]=id.split('|');PrintDesign.localize(()=>receipt(tid,pid));}
  if(a==='next'){C.mainBill(m());if(C.totals(m()).invalid)throw Error('reading');confirmAction(tr('Start next month?','পরের মাস শুরু করবেন?'),tr(`This finalizes ${monthLabel(state.active)}, copies current readings to previous readings, and carries unpaid balances into ${monthLabel(C.nextKey(state.active))}. New readings start at the same value. Extra charges and custom rates are kept; the due date is cleared.`,`এতে ${monthLabel(state.active)} চূড়ান্ত হবে। বর্তমান রিডিং পূর্ববর্তী হবে এবং বকেয়া ${monthLabel(C.nextKey(state.active))}-এ যাবে। নতুন রিডিং একই থাকবে। অতিরিক্ত চার্জ ও নিজস্ব দর থাকবে; শেষ তারিখ খালি হবে।`),'next-confirm',tr('Carry over & start month','পরের মাস শুরু করুন'));}
  if(a==='next-confirm'){const source=m();C.carry(state);source.finalizedAt=source.finalizedAt||C.today();delete m().finalizedAt;$('#editor').close();query='';filter='all';Features.markFinalized();render();notice(tr('New month created. Readings and unpaid balances were carried forward. Set the new due date.','নতুন মাস তৈরি হয়েছে। রিডিং ও বকেয়া আনা হয়েছে। নতুন শেষ তারিখ লিখুন।'));}
  if(a==='finalize'){if(m().finalizedAt)return notice(tr('This month is already finalized.','এই মাস চূড়ান্ত করা আছে।'));if(C.totals(m()).invalid)throw Error('reading');C.mainBill(m());confirmAction(tr('Finalize this month?','এই মাস চূড়ান্ত করবেন?'),tr('Readings and charges will be locked. You can still record payments. You must reopen the month to edit bills. Late fees are fixed as of today.','রিডিং ও চার্জ লক হবে। পেমেন্ট নেওয়া যাবে। বিল পরিবর্তনে মাস পুনরায় খুলতে হবে। আজকের হিসাবে বিলম্ব ফি স্থির হবে।'),'finalize-confirm',tr('Finalize month','মাস চূড়ান্ত করুন'));}
  if(a==='finalize-confirm'){m().finalizedAt=C.today();Features.markFinalized();$('#editor').close();render();}
  if(a==='reopen')confirmAction(tr('Reopen this month?','এই মাস আবার খুলবেন?'),tr('Changes will affect issued bills. Later months’ carried arrears will not change automatically; review them manually. Late fees will use today’s date again.','পরিবর্তনে ইস্যু করা বিল বদলাবে। পরের মাসগুলোর বকেয়া স্বয়ংক্রিয়ভাবে বদলাবে না; নিজে যাচাই করুন। বিলম্ব ফি আবার আজকের হিসাবে হবে।'),'reopen-confirm',tr('Reopen month','মাস আবার খুলুন'));
  if(a==='reopen-confirm'){delete m().finalizedAt;$('#editor').close();render();}
  if(a==='open-month'){state.active=id;query='';filter='all';location.hash='billing';view='billing';render();}
  if(a==='suggest-rate'){if(m().finalizedAt)return notice(tr('Reopen the month before changing its rate.','দর পরিবর্তনের আগে মাস পুনরায় খুলুন।'),true);const s=C.totals(m());if(!s.units||s.invalid)return notice(tr('Enter valid tenant consumption first.','প্রথমে সঠিক ভাড়াটিয়ার ব্যবহার লিখুন।'),true);m().rate=C.round(actual()/s.units);render();notice(tr('Shared rate updated. Custom flat rates are preserved.','সাধারণ দর বদলেছে। ফ্ল্যাটের নিজস্ব দর অপরিবর্তিত।'));}
  if(a==='preset'){if(m().finalizedAt)return;const preset=m().main.preset;if(preset==='custom')return;confirmAction(tr('Replace tariff rates?','ট্যারিফ দর বদলাবেন?'),tr('This replaces the seven energy rates and slab limits for this month. Connection settings stay as entered.','এই মাসের সাতটি দর ও সীমা বদলাবে। সংযোগের সেটিংস অপরিবর্তিত থাকবে।'),'preset-confirm:'+preset,tr('Apply preset','প্রিসেট প্রয়োগ'));}
  if(a.startsWith('preset-confirm:')){const p=a.slice(15);m().main.rates=p==='2024-02'?[4.63,5.26,7.20,7.59,8.02,12.67,14.61]:[...C.rates];m().main.limits=[...C.limits];m().main.preset=p;$('#editor').close();render();}
  if(a==='backup')backup();if(a==='csv')csvExport();if(a==='import')$('#importFile').click();
  if(a==='import-confirm'){if(!pendingImport)return;backup();state=pendingImport;pendingImport=null;storageBlocked=false;lastSavedRaw=localStorage.getItem(KEY);$('#editor').close();save();render();notice(tr('Backup restored. A backup of the previous in-memory records was also downloaded.','ব্যাকআপ ফিরেছে। আগের মেমরিতে থাকা হিসাবের ব্যাকআপও ডাউনলোড হয়েছে।'));}
  if(a==='whatsapp'||a==='sms')BillMessaging.send(a,id);
  if(a==='copy-bill')await BillMessaging.copy(id);
  if(a==='select-bill-text'){$('#messageCopyText').focus();$('#messageCopyText').select();}
  if(a==='share'){const text=billText(flat(id));if(navigator.share){try{await navigator.share({title:BillMessaging.language()==='bn'?'বিদ্যুৎ বিল':'Electricity bill',text});}catch(err){if(err.name!=='AbortError')notice(tr('Sharing is unavailable. Use WhatsApp or Print / Save PDF.','শেয়ার করা যায়নি। হোয়াটসঅ্যাপ বা প্রিন্ট / PDF ব্যবহার করুন।'),true);}}else{try{await navigator.clipboard.writeText(text);notice(tr('Bill text copied. Paste it into your messaging app.','বিলের লেখা কপি হয়েছে। মেসেজ অ্যাপে পেস্ট করুন।'));}catch{notice(tr('Use WhatsApp draft or Print / Save PDF on this browser.','এই ব্রাউজারে হোয়াটসঅ্যাপ খসড়া অথবা প্রিন্ট / PDF ব্যবহার করুন।'));}}}
}catch(err){notice(errorText(err),true);}});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('size');const raw=JSON.parse(await file.text());pendingImport=C.validate(raw);confirmAction(tr('Restore this backup?','এই ব্যাকআপ ফেরাবেন?'),tr(`Replace current records with ${Object.keys(raw.months).length} saved month(s) from “${esc(raw.building||'Building Ledger')}”? A copy of the current records will be downloaded first.`,`বর্তমান হিসাব বদলে “${esc(raw.building||'Building Ledger')}”-এর ${num(Object.keys(raw.months).length)}টি মাস আনবেন? প্রথমে বর্তমান হিসাব ডাউনলোড হবে।`),'import-confirm',tr('Restore backup','ব্যাকআপ ফেরান'));}catch{pendingImport=null;notice(tr('This backup is invalid or too large (maximum 10 MB). No records were changed. Choose a Building Ledger JSON backup.','ব্যাকআপ সঠিক নয় বা ১০ MB-এর বেশি। কোনো হিসাব বদলায়নি। Building Ledger-এর JSON ব্যাকআপ বাছুন।'),true);}});
$('#language').addEventListener('click',()=>{state.lang=state.lang==='en'?'bn':'en';render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue!==lastSavedRaw&&!storageBlocked)storageConflict();});
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);if(['billing','main','history','settings'].includes(name)){view=name;render();$('#workspace').focus();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install').hidden=false;});
$('#install').addEventListener('click',async()=>{if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#install').hidden=true;}});
window.addEventListener('offline',()=>notice(tr('Offline. Changes continue to save on this device.','অফলাইন। পরিবর্তন এই ডিভাইসে সংরক্ষিত হবে।')));
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>notice(tr('Offline installation could not be enabled. The calculator still works while this page is open.','অফলাইন ইনস্টল চালু হয়নি। পেজ খোলা থাকলে হিসাব করা যাবে।')));
view=['billing','main','history','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'billing';render();if(startupMessage)notice(startupMessage,storageBlocked);
